const chopTimes: number[] = [];
while (countLogs() < 8) {
  const tree = sdk.getState()?.nearbyLocs
    .filter(l => /^(tree|dead tree)$/i.test(l.name))
    .filter(l => l.optionsWithIndex.some(o => /chop/i.test(o.text)))
