  const t = Date.now();
  await sdk.sendInteractLoc(tree.x, tree.z, tree.id, 1);
  try {
    await sdk.waitForCondition(s => s.inventory.filter(i => /logs$/i.test(i.name)).length > before, 15000);
    chopTimes.push(Date.now() - t);
  } catch { console.log('chop timeout'); }
}
