import { runScript } from '/app/sdk/runner';

const STRENGTH_PHASE_MS = 5.5 * 60 * 1000; // train str first (multiplies def XP later)
const TOTAL_MS = 15 * 60 * 1000;           // total budget for this script

const t0 = Date.now();
const log = (...a: any[]) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s]`, ...a);

function pickTarget(st: any) {
  const cbt = st.player.combat;
  const targetAlive =
    cbt.inCombat && cbt.targetIndex >= 0 && st.nearbyNpcs.some((n: any) => n.index === cbt.targetIndex);
  if (targetAlive) return null;
  const order = [/^imp$/i, /^giant rat$/i, /^man$/i, /^woman$/i, /^duck$/i, /^rat$/i];
  const cands = st.nearbyNpcs
    .filter((n: any) => n.optionsWithIndex.some((o: any) => /^attack$/i.test(o.text)))
    .filter((n: any) => n.reachable !== false);
  for (const pat of order) {
    const m = cands.filter((n: any) => pat.test(n.name)).sort((a: any, b: any) => a.distance - b.distance);
    if (m.length) return m[0];
  }
  return null;
}

