// preference: which ore to mine given mining level
function bestOre(level: number): string[] {
  if (level >= 85) return ['runite', 'adamantite', 'mithril', 'gold', 'coal'];
  if (level >= 70) return ['adamantite', 'mithril', 'runite', 'gold', 'coal'];
  if (level >= 55) return ['mithril', 'adamantite', 'gold', 'coal'];
  if (level >= 40) return ['gold', 'coal', 'mithril', 'silver'];
  if (level >= 30) return ['coal', 'gold', 'silver', 'iron'];
  if (level >= 20) return ['silver', 'coal', 'iron', 'gold'];
  if (level >= 15) return ['iron', 'silver', 'copper', 'tin'];
  return ['copper', 'tin', 'iron'];
}

